CREATE TABLE IF NOT EXISTS schema_migrations (
  version INTEGER PRIMARY KEY,
  applied_at TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS devices_presence_key_idx
  ON devices(presence_public_key_fingerprint)
  WHERE presence_public_key_fingerprint IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS inference_active_per_node_idx
  ON inference_instances(node_id)
  WHERE state IN ('loading','ready','idle','draining','unloading');

CREATE UNIQUE INDEX IF NOT EXISTS cluster_launches_one_active_per_cluster
  ON cluster_launches(cluster_id)
  WHERE state IN ('preparing','running','degraded','stopping');

CREATE UNIQUE INDEX IF NOT EXISTS builds_worker_claim_request_idx
  ON builds(worker_id, claim_request_id)
  WHERE claim_request_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS development_workspaces (
    project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
    worktree_id TEXT NOT NULL UNIQUE REFERENCES project_worktrees(id),
    image_digest TEXT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE TABLE household_members (
    device_id TEXT PRIMARY KEY REFERENCES devices(id),
    added_by TEXT NOT NULL REFERENCES devices(id),
    added_at TEXT NOT NULL
);
